function historyMessageText(message) {
  return String(message?.content ?? "").trim();
}

function historyDuration(session) {
  const seconds = Math.round((new Date(session.ended_at) - new Date(session.started_at)) / 1000);
  if (!Number.isFinite(seconds) || seconds < 0) return "";
  if (seconds < 60) return seconds + " 秒";
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return minutes + " 分钟";
  return Math.floor(minutes / 60) + " 小时" + (minutes % 60 ? " " + minutes % 60 + " 分钟" : "");
}

function historyDay(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "日期未知";
  const today = new Date();
  const yesterday = new Date(today);
  yesterday.setDate(today.getDate() - 1);
  if (date.toDateString() === today.toDateString()) return "今天";
  if (date.toDateString() === yesterday.toDateString()) return "昨天";
  return date.toLocaleDateString("zh-CN", {
    month: "long", day: "numeric", ...(date.getFullYear() !== today.getFullYear() ? { year: "numeric" } : {}),
  });
}

function renderHistoryMessage(message) {
  const role = message.role || "unknown";
  const row = el("div", "history-entry " + role);
  const node = renderMessage(message);
  if (role !== "tool") {
    const avatar = el("div", "history-avatar");
    avatar.setAttribute("aria-hidden", "true");
    avatar.append(historyIcon(role));
    row.append(avatar);
  }
  if (role === "user" && node.querySelector(".role").textContent === ROLE_LABEL.user) node.querySelector(".role").textContent = "你";
  if (role === "tool") {
    const summary = node.querySelector("summary");
    if (summary) {
      node.querySelector(".head").remove();
      summary.textContent = "工具结果 · " + String(message.content).length + " 字";
    }
  }
  row.append(node);
  return row;
}

function renderHistoryMeta(session) {
  const meta = $("#history-meta");
  const heading = el("div", "history-title-row");
  const title = historyMessageText(session.messages.find((message) => message.role === "user")) || "会话记录";
  const name = el("h3", null, title.replace(/\s+/g, " "));
  name.title = title;
  heading.append(name, el("span", "history-ended", "已结束"));
  const subtitle = el("div", "history-session-subtitle");
  for (const text of [historyTime(session.started_at), historyDuration(session), session.messages.length + " 条消息"]) {
    if (text) subtitle.append(el("span", null, text));
  }
  const info = el("details", "history-session-info");
  const summary = el("summary");
  summary.append(historyIcon("info"), document.createTextNode("会话信息"));
  const panel = el("div", "history-info-panel");
  const description = el("dl");
  for (const [label, value] of [["会话 ID", session.id], ["开始时间", historyTime(session.started_at)],
                               ["结束时间", historyTime(session.ended_at)]]) {
    description.append(el("dt", null, label), el("dd", label === "会话 ID" ? "history-id" : null, value));
  }
  panel.append(description);
  info.append(summary, panel);
  meta.replaceChildren(heading, subtitle, info);
}

async function historyFetch(url, request) {
  const res = await fetch(url, { signal: request.signal, cache: "no-store" });
  const data = await res.json();
  if (!res.ok || !data.ok) throw new Error(data.error || "查询失败，请重试");
  return data;
}

