    button.setAttribute("aria-pressed", String(button.dataset.sessionId === sessionId));
  }
  $("#history-meta").replaceChildren();
  $("#history-messages").replaceChildren(historyPlaceholder("正在加载对话…"));
  try {
    const data = await historyFetch("/api/sessions/" + encodeURIComponent(sessionId), request);
    if (request !== historyDetailRequest || !$("#history-dialog").open) return;
    const session = data.session;
