async function loadHistory(offset = 0) {
  if (historyListRequest) historyListRequest.abort();
  if (historyDetailRequest) historyDetailRequest.abort();
  const request = historyListRequest = new AbortController();
  $(".history-layout").classList.remove("history-show-detail");
  $("#history-list-label").textContent = historyQuery ? "搜索结果" : "全部会话";
  $("#history-status").textContent = "查询中…";
  $("#history-list").replaceChildren();
  $("#history-list").setAttribute("aria-busy", "true");
  $("#history-meta").replaceChildren();
  $("#history-messages").replaceChildren(historyPlaceholder("选择一段对话", "在会话列表中选择，查看聊天记录"));
  $("#history-prev").disabled = $("#history-next").disabled = true;
  $("#history-page").textContent = "";
  try {
    const params = new URLSearchParams({ q: historyQuery, limit: HISTORY_PAGE_SIZE, offset });
    const data = await historyFetch("/api/sessions?" + params, request);
    if (request !== historyListRequest || !$("#history-dialog").open) return;
    historyOffset = data.offset;
    $("#history-status").textContent = data.total + " 个";
    $("#history-page").textContent = data.total ? (Math.floor(data.offset / data.limit) + 1)
      + " / " + Math.ceil(data.total / data.limit) : "";
    $("#history-prev").disabled = data.offset === 0;
    $("#history-next").disabled = data.offset + data.sessions.length >= data.total;
    const nodes = [];
    let lastDay = null;
    for (const session of data.sessions) {
      const day = historyDay(session.started_at);
      if (day !== lastDay) nodes.push(el("div", "history-date", day));
      lastDay = day;
      const button = el("button", "history-item");
      button.type = "button";
      button.dataset.sessionId = session.id;
      button.setAttribute("aria-pressed", "false");
      const content = el("span", "history-item-content");
      content.append(el("span", "history-preview", session.preview || "未命名会话"));
      const clock = new Date(session.started_at).toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit", hour12: false });
      content.append(el("span", "history-item-meta", clock + " · " + session.message_count + " 条消息"));
      button.append(historyIcon(), content);
      button.addEventListener("click", () => loadHistoryDetail(session.id));
      nodes.push(button);
    }
    $("#history-list").replaceChildren(...(nodes.length ? nodes : [historyPlaceholder(historyQuery
      ? "没有找到相关对话" : "还没有历史会话", historyQuery ? "换一个关键词，或清空搜索再试试" : "会话结束后，记录会保存在这里")]));
    if (data.sessions.length) loadHistoryDetail(data.sessions[0].id, false);
  } catch (error) {
    if (error.name === "AbortError" || request !== historyListRequest) return;
    $("#history-status").textContent = "加载失败";
    $("#history-list").replaceChildren(historyPlaceholder("暂时无法加载", error.message, true));
  } finally {
    if (request === historyListRequest) $("#history-list").setAttribute("aria-busy", "false");
  }
}

