async function sendText() {
  const box = $("#send-text");
  const text = box.value.trim();
  if (!text || sending) return;
  sending = true;
  $("#send").disabled = true;
  $("#send-note").textContent = "";
  try {
    const res = await fetch("/api/send", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text }),
    });
    const data = await res.json();
    if (data.ok) {
      box.value = "";
    } else {
      $("#send-note").textContent = data.error || "发送失败";
      $("#send-note").className = "err";
    }
  } catch (e) {
    $("#send-note").textContent = String(e);
    $("#send-note").className = "err";
  } finally {
    sending = false;
    $("#send").disabled = false;
    box.focus();
  }
}

$("#send").addEventListener("click", sendText);
$("#send-text").addEventListener("keydown", (event) => {
  if (event.key === "Enter" && !event.shiftKey && !event.isComposing) {  // 中文输入法选词的回车不算发送
