<script>
const $ = (sel) => document.querySelector(sel);
let month = "";         // 正在显示的月份 YYYY-MM
let selected = "";      // 选中的日期 YYYY-MM-DD
let entries = {};       // 当前月份：日期 → 日记
let range = { first: "", last: "" };  // 全部日记的日期范围，翻月和「跳到最近一篇」用
let monthRequest = null;
let memoryDirty = false;  // 记忆框有没保存的改动时，刷新不覆盖它
let memorySaving = false;
let diaryState = {};      // 服务端整理状态（SSE 推送的 status.diary）
let lastFinishedAt = null;
let requestedFrom = null;  // 点「立即整理」时的 finished_at；它变了说明这一轮已经结束

function el(tag, cls, text) {
  const node = document.createElement(tag);
  if (cls) node.className = cls;
  if (text !== undefined) node.textContent = text;
  return node;
}

const pad = (n) => String(n).padStart(2, "0");
const ymd = (date) => date.getFullYear() + "-" + pad(date.getMonth() + 1) + "-" + pad(date.getDate());
const today = () => ymd(new Date());

function parseDate(value) {  // 日记日期是本地日期，按年月日构造，避免 new Date(str) 当成 UTC 零点
  const [year, mon, day] = value.split("-").map(Number);
  return new Date(year, mon - 1, day || 1);
}

function shiftMonth(value, delta) {
  const date = parseDate(value + "-01");
  date.setMonth(date.getMonth() + delta);
  return date.getFullYear() + "-" + pad(date.getMonth() + 1);
}

function dateLabel(value) {
  const date = parseDate(value);
  return date.getFullYear() + "年" + (date.getMonth() + 1) + "月" + date.getDate() + "日 星期" + "日一二三四五六"[date.getDay()];
}

function shortDate(value) {
  const date = parseDate(value);
  return (date.getMonth() + 1) + "月" + date.getDate() + "日";
}

function clock(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "" : date.toLocaleString("zh-CN", {
    month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit", hour12: false,
  });
}

// ---------------- 月历 ----------------

function renderCalendar() {
  const [year, mon] = month.split("-").map(Number);
  $("#cal-title").textContent = year + "年" + mon + "月";
  const lead = (new Date(year, mon - 1, 1).getDay() + 6) % 7;  // 周一开头
  const days = new Date(year, mon, 0).getDate();
  const now = today();
  const cells = [];
  for (let i = 0; i < lead; i++) cells.push(el("div"));
  for (let day = 1; day <= days; day++) {
    const date = month + "-" + pad(day);
    const entry = entries[date];
    const cell = el("button", "cal-day" + (entry ? " has-diary" : "") + (date === now ? " today" : ""));
    cell.type = "button";
    cell.dataset.date = date;
    cell.disabled = date > now && !entry;  // 还没到的日子
    cell.setAttribute("aria-pressed", String(date === selected));
    cell.setAttribute("aria-label", dateLabel(date) + (entry ? "，" + entry.session_count + " 次对话" : "，没有日记"));
    const num = el("span", "cal-num", String(day));
    if (date === now) num.append(el("span", "cal-tag", "今天"));
    cell.append(num);
    if (entry) cell.append(el("span", "cal-preview", entry.content), el("span", "cal-count", entry.session_count + " 次对话"));
    cell.addEventListener("click", () => select(date));
    cells.push(cell);
  }
  $("#cal-days").replaceChildren(...cells);

  const latestMonth = range.last.slice(0, 7);
  $("#cal-prev").disabled = !range.first || month <= range.first.slice(0, 7);
  $("#cal-next").disabled = month >= (latestMonth > now.slice(0, 7) ? latestMonth : now.slice(0, 7));
  const count = Object.keys(entries).length;
  const foot = $("#cal-foot");
  foot.className = "cal-foot";
  foot.replaceChildren(el("span", null, count ? "本月 " + count + " 篇日记" : range.last ? "本月还没有日记" : "还没有日记，会话结束后每小时自动整理"));
  if (range.last && !range.last.startsWith(month)) {
