function renderMemory(memory) {
  $("#memory-text").value = memory.content || "";
  const source = memory.source === "manual" ? (memory.content ? "手动修改" : "已清空") : "自动整理";
  $("#memory-meta").textContent = memory.updated_at ? source + " · " + clock(memory.updated_at) : "";
  memoryDirty = false;
  $("#memory-save").disabled = true;
}

async function loadMemory() {
  try {
    const res = await fetch("/api/memory", { cache: "no-store" });
    const data = await res.json();
    if (!res.ok || !data.ok) throw new Error(data.error || "读取失败");
    if (!memoryDirty) renderMemory(data.memory);  // 加载期间开始编辑的话，保留编辑内容
  } catch (error) {
    memoryNote("读取记忆失败：" + (error.message || error), false);
  }
}

async function saveMemory(content, success) {
  if (memorySaving) return;
  memorySaving = true;
  $("#memory-save").disabled = $("#memory-clear").disabled = true;
  memoryNote("正在保存…", true);
  try {
    const res = await fetch("/api/memory", {
      method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ content }),
    });
    const data = await res.json();
    if (!res.ok || !data.ok) throw new Error(data.error || "保存失败");
    renderMemory(data.memory);
    memoryNote(success, true);
