$("#cal-prev").addEventListener("click", () => loadMonth(shiftMonth(month, -1)));
$("#cal-next").addEventListener("click", () => loadMonth(shiftMonth(month, 1)));
$("#cal-today").addEventListener("click", () => loadMonth(today().slice(0, 7), today()));
