loadMemory();
const initial = /^#\d{4}-\d{2}-\d{2}$/.test(location.hash) ? location.hash.slice(1) : "";
loadMonth((initial || today()).slice(0, 7), initial).then(() => {
  // 直接打开且本月还没有日记时，跳到最近有日记的月份
  if (!initial && !Object.keys(entries).length && range.last) loadMonth(range.last.slice(0, 7), range.last);
