.composer { display:flex; gap:8px; align-items:flex-end; margin-top:12px; padding-top:12px; border-top:1px solid var(--line); }
.composer textarea { flex:1; resize:none; }
.composer button { flex:none; }
#send-note { font-size:12px; margin-top:6px; min-height:1.6em; }
#send-note.err { color:var(--err); }
#history-dialog {
  --history-soft:color-mix(in srgb, var(--accent) 7%, var(--card));
  --history-panel:color-mix(in srgb, var(--bg) 65%, var(--card));
  width:min(1120px, calc(100vw - 48px)); height:90vh; height:min(800px, 90dvh);
  max-width:none; max-height:none; padding:0; overflow:hidden;
  border:1px solid color-mix(in srgb, var(--line) 80%, transparent); border-radius:16px;
  background:var(--card); color:var(--fg); box-shadow:0 24px 90px #0b18313b;
}
#history-dialog[open] { display:flex; }
#history-dialog::backdrop { background:#10182866; backdrop-filter:blur(3px); }
#history-dialog button:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }
.history-icon { display:block; width:18px; height:18px; flex:none; fill:none; stroke:currentColor; stroke-width:1.65; stroke-linecap:round; stroke-linejoin:round; }
.history-close { position:absolute; top:16px; right:16px; z-index:3; display:grid; place-items:center; width:30px; height:30px; padding:0; border:0; color:var(--muted); background:transparent; }
.history-close:hover { color:var(--fg); background:var(--bg); }
.history-layout { display:grid; grid-template-columns:300px minmax(0, 1fr); width:100%; min-height:0; }
.history-sidebar { display:flex; flex-direction:column; min-height:0; background:var(--history-panel); border-right:1px solid var(--line); }
.history-sidebar-head { padding:24px 20px 16px; }
.history-heading { display:flex; align-items:center; gap:9px; margin-bottom:20px; }
.history-heading > .history-icon { color:var(--accent); width:20px; height:20px; }
.history-heading h2 { margin:0; font-size:17px; font-weight:650; letter-spacing:-.3px; }
.history-searchbox { display:flex; align-items:center; gap:8px; padding:6px 8px 6px 10px; border:1px solid var(--line); border-radius:8px; background:var(--card); }
.history-searchbox:focus-within { border-color:color-mix(in srgb, var(--accent) 60%, var(--line)); box-shadow:0 0 0 3px var(--history-soft); }
#history-search .history-icon { width:15px; height:15px; color:var(--muted); }
#history-query { flex:1; min-width:0; padding:2px 0; border:0; border-radius:0; background:transparent; font-size:12px; outline:none; }
#history-search button { flex:none; padding:2px 5px; border:0; border-radius:4px; color:var(--accent); background:transparent; font-size:11px; }
#history-search button:hover { background:var(--history-soft); }
.history-list-head { display:flex; justify-content:space-between; gap:8px; padding:0 22px 6px; color:var(--muted); font-size:11px; }
#history-status { font-variant-numeric:tabular-nums; }
#history-list { flex:1; min-height:0; overflow-y:auto; padding:0 12px 12px; scrollbar-width:thin; scrollbar-color:var(--line) transparent; }
.history-date { padding:14px 10px 6px; color:var(--muted); font-size:11px; }
.history-item { display:flex; align-items:flex-start; gap:10px; width:100%; margin:3px 0; padding:11px 10px; text-align:left; border:1px solid transparent; border-radius:9px; background:transparent; }
.history-item:hover { background:color-mix(in srgb, var(--card) 75%, transparent); }
.history-item[aria-pressed="true"] { background:var(--card); border-color:color-mix(in srgb, var(--accent) 22%, var(--line)); box-shadow:0 2px 5px #10182806; }
.history-item > .history-icon { width:16px; height:16px; margin-top:2px; color:var(--muted); }
.history-item[aria-pressed="true"] > .history-icon { color:var(--accent); }
.history-item-content { display:block; flex:1; min-width:0; }
.history-preview { display:block; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; font-size:12.5px; font-weight:500; }
.history-item[aria-pressed="true"] .history-preview { color:var(--accent); }
.history-item-meta { display:block; color:var(--muted); font-size:11px; margin-top:4px; }
.history-pagination { display:flex; align-items:center; justify-content:space-between; gap:6px; padding:12px 18px; border-top:1px solid var(--line); }
.history-pagination button { display:flex; align-items:center; gap:3px; padding:4px 6px; border:0; background:transparent; font-size:11px; color:var(--muted); }
.history-pagination button:hover:not(:disabled) { color:var(--accent); }
.history-pagination .history-icon { width:13px; height:13px; }
#history-page { color:var(--muted); font-size:11px; font-variant-numeric:tabular-nums; }
.history-detail { display:flex; flex-direction:column; min-width:0; min-height:0; background:var(--card); }
#history-back { display:none; }
#history-meta:not(:empty) { flex:none; position:relative; padding:25px 58px 20px 30px; border-bottom:1px solid var(--line); }
.history-title-row { display:flex; align-items:center; gap:12px; min-width:0; }
#history-meta h3 { flex:1; min-width:0; margin:0; font-size:17px; font-weight:600; letter-spacing:-.2px; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; }
.history-ended { display:inline-flex; align-items:center; gap:5px; flex:none; border-radius:5px; padding:2px 6px; color:var(--muted); background:var(--bg); font-size:10px; }
.history-ended::before { content:""; width:4px; height:4px; border-radius:50%; background:var(--muted); }
.history-session-subtitle { display:flex; flex-wrap:wrap; gap:6px 12px; margin-top:7px; font-size:11px; color:var(--muted); }
.history-session-subtitle span + span::before { content:"·"; margin-right:12px; opacity:.6; }
.history-session-info { position:absolute; right:30px; bottom:19px; z-index:2; }
.history-session-info summary { display:flex; align-items:center; gap:4px; list-style:none; font-size:11px; }
.history-session-info summary::-webkit-details-marker { display:none; }
.history-session-info summary:hover, .history-session-info[open] summary { color:var(--accent); }
.history-session-info summary .history-icon { width:13px; height:13px; }
.history-info-panel { position:absolute; top:26px; right:0; width:300px; padding:14px 16px; border:1px solid var(--line); border-radius:10px; background:var(--card); box-shadow:0 8px 28px #10182815; }
.history-info-panel dl { display:grid; grid-template-columns:auto minmax(0, 1fr); gap:8px 14px; margin:0; font-size:11px; }
.history-info-panel dt { color:var(--muted); }
.history-info-panel dd { margin:0; overflow-wrap:anywhere; }
.history-id { font-family:ui-monospace, SFMono-Regular, Menlo, monospace; }
#history-messages { flex:1; min-height:0; overflow-y:auto; padding:28px 30px; background:color-mix(in srgb, var(--bg) 36%, var(--card)); scrollbar-width:thin; scrollbar-color:var(--line) transparent; }
.history-entry { display:flex; align-items:flex-start; gap:10px; max-width:680px; margin:0 auto 22px; }
.history-avatar { display:grid; place-items:center; flex:none; width:28px; height:28px; margin-top:2px; border:1px solid var(--line); border-radius:9px; background:var(--card); color:var(--muted); font-size:10px; font-weight:650; }
.history-avatar .history-icon { width:15px; height:15px; }
.history-entry.assistant .history-avatar { color:var(--fg); }
.history-entry.user { flex-direction:row-reverse; padding-left:48px; }
.history-entry.user .history-avatar { color:var(--accent); background:var(--history-soft); border-color:transparent; }
#history-messages .msg { flex:0 1 auto; min-width:0; max-width:calc(100% - 38px); margin:0; padding:12px 15px; border:1px solid var(--line); border-radius:2px 12px 12px; background:var(--card); }
#history-messages .msg.user { background:var(--history-soft); border-color:transparent; border-radius:12px 2px 12px 12px; }
#history-messages .msg .head { align-items:center; gap:10px; margin-bottom:5px; }
#history-messages .msg .role { font-size:11px; color:var(--muted); font-weight:500; }
#history-messages .msg.user .role { color:var(--accent); }
#history-messages .msg .meta { font-size:10px; color:var(--muted); }
#history-messages .body { margin:0; font-size:13px; line-height:1.85; }
.history-entry.tool { padding:0 0 0 38px; margin-top:-10px; margin-bottom:20px; }
#history-messages .msg.tool { padding:8px 12px; border-style:dashed; border-radius:8px; background:transparent; }
#history-messages .msg.tool summary { font-size:11px; }
#history-messages details pre { margin-top:8px; font-size:11px; }
.history-placeholder { display:flex; flex-direction:column; align-items:center; justify-content:center; gap:8px; min-height:180px; height:100%; padding:28px 20px; text-align:center; color:var(--muted); }
.history-placeholder > .history-icon { width:30px; height:30px; margin-bottom:4px; opacity:.45; stroke-width:1.2; }
.history-placeholder strong { color:var(--fg); font-size:13px; font-weight:500; }
.history-placeholder span { font-size:11px; line-height:1.8; }
.history-placeholder.history-error strong { color:var(--err); }
.history-sr-only { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0, 0, 0, 0); white-space:nowrap; border:0; }
@media (max-width:720px) {
  #history-dialog { width:calc(100vw - 24px); height:92vh; height:92dvh; border-radius:12px; }
  .history-layout { display:block; }
  .history-sidebar, .history-detail { height:100%; border:0; }
  .history-detail { display:none; }
  .history-show-detail .history-sidebar { display:none; }
  .history-show-detail .history-detail { display:flex; }
  .history-sidebar-head { padding:23px 20px 18px; }
  .history-heading { margin-bottom:22px; }
  .history-pagination { padding:14px 20px; }
  #history-back { display:flex; align-items:center; gap:5px; align-self:flex-start; margin:20px 56px 0 20px; padding:0; border:0; font-size:11px; background:transparent; color:var(--muted); }
  #history-back .history-icon { width:13px; height:13px; }
  #history-meta:not(:empty) { padding:18px 20px 38px; }
  #history-meta h3 { font-size:16px; }
  .history-session-info { right:20px; bottom:12px; }
  .history-info-panel { width:min(300px, calc(100vw - 64px)); }
  #history-messages { padding:22px 16px; }
  .history-entry { gap:7px; }
  .history-entry.user { padding-left:18px; }
  .history-entry.tool { padding-left:35px; }
  #history-messages .msg { padding:10px 12px; max-width:calc(100% - 35px); }
}
</style>
</head>
<body>

<header>
  <h1>harness 终端</h1>
    <datalist id="voiceprint-names"></datalist>
    <button id="voiceprint-save" class="primary" type="submit">保存声纹</button>
  </form>
  <p id="voiceprint-note" class="note" role="status" aria-live="polite"></p>
  <div id="voiceprint-profiles"></div>
</dialog>

<dialog id="history-dialog" aria-labelledby="history-title">
  <button id="history-close" class="history-close" type="button" aria-label="关闭历史会话" title="关闭（Esc）">
    <svg class="history-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M6 18 18 6"/></svg>
  </button>
  <div class="history-layout">
    <aside class="history-sidebar" aria-label="会话列表">
      <div class="history-sidebar-head">
        <div class="history-heading">
          <svg class="history-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H8l-5 3V6a2 2 0 0 1 2-2ZM7 9h10M7 13h6"/></svg>
          <h2 id="history-title">历史会话</h2>
        </div>
        <form id="history-search">
          <div class="history-searchbox">
            <label class="history-sr-only" for="history-query">搜索消息内容或会话 ID</label>
            <svg class="history-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>
            <input id="history-query" type="search" maxlength="200" placeholder="搜索对话或会话 ID" autofocus>
            <button type="submit">搜索</button>
          </div>
        </form>
      </div>
      <div class="history-list-head">
        <span id="history-list-label">全部会话</span>
        <span id="history-status" role="status" aria-live="polite"></span>
      </div>
      <div id="history-list"></div>
      <div class="history-pagination">
        <button id="history-prev" type="button" disabled><svg class="history-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg>上一页</button>
        <span id="history-page"></span>
        <button id="history-next" type="button" disabled>下一页<svg class="history-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m10 6 6 6-6 6"/></svg></button>
      </div>
    </aside>
    <section class="history-detail" aria-label="会话消息">
      <button id="history-back" type="button"><svg class="history-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg>返回列表</button>
      <div id="history-meta" aria-live="polite"></div>
      <div id="history-messages"></div>
    </section>
  </div>
</dialog>

<script>
const $ = (sel) => document.querySelector(sel);
const ROLE_LABEL = { system: "系统", user: "用户", assistant: "助手", tool: "工具" };
let lastSig = null;      // 消息没变就不重画，免得看到一半被刷掉
let systemOpen = false;  // 系统提示词的展开状态自己记着，重画后还原
let compressOpen = false;  // 压缩摘要折叠块的展开状态，同上
let jsonMode = false;    // MCP 配置的两种编辑方式：一行一个 server / 整段 JSON
let skillsSig = null;    // 技能列表重取时没变就不重建（重建会把展开的行收起来）
let skillsDir = "";      // 技能目录，空态文案要用
let busy = false;
let fullState = {};  // 最近一次完整状态；SSE 只推会变的那几项，合并进来再画
let messages = [];   // 当前 llm.messages；SSE 只推新增的，按 start 往后拼
let sending = false;  // 发文本时禁用发送按钮，别连点发出重复的两句

function el(tag, cls, text) {
  const node = document.createElement(tag);
  if (cls) node.className = cls;
  if (text !== undefined) node.textContent = text;
  return node;
}

// ---------------- 外部 MCP servers ----------------

function splitCommand(line) {  // 够用的 shlex：按空白切，引号里的空格不切
  const parts = [];
  });
  audio.addEventListener("timeupdate", () => {
    if (audio.duration) chip.style.setProperty("--p", (audio.currentTime / audio.duration * 100) + "%");
  });
  audio.addEventListener("play", () => {
    if (playingVoice && playingVoice !== audio) playingVoice.pause();
    playingVoice = audio;
    chip.classList.add("playing");
  });
  const reset = () => { chip.classList.remove("playing"); chip.style.setProperty("--p", "0%"); };
  audio.addEventListener("pause", reset);
  audio.addEventListener("ended", reset);
  audio.addEventListener("error", () => { chip.classList.add("err"); label.textContent = "录音不可用"; });
  chip.addEventListener("click", () => {
    if (chip.classList.contains("err")) return;
    if (audio.paused) audio.play(); else audio.pause();
  });
  return chip;
}

function renderMessage(m, live = false) {
  const wrap = el("div", "msg " + m.role);
  const head = el("div", "head");
  head.append(el("span", "role", (m.role === "user" && m.speaker) || ROLE_LABEL[m.role] || m.role));

  let body = m.content == null ? "" : String(m.content);
  let meta = (m.time || "").slice(11, 19);  // 每条 message 都带 time（ISO），取 HH:MM:SS
  let instructions = "";  // 工具调用后 SDK 自动补的一轮：text 为空、只带 response_instructions
  if (live && m.role === "user") {
    try {  // 实时 SDK 的 user content 是 JSON；历史消息直接显示已入库的正文。
      const payload = JSON.parse(body);
      if (payload && typeof payload === "object" && "text" in payload) {
        body = payload.text || "";
        if (payload.speaker) head.querySelector(".role").textContent = payload.speaker;
        instructions = payload.response_instructions || "";
        meta = [payload.round ? "第 " + payload.round + " 轮" : "", meta || (payload.time || "").slice(11, 19)]
          .filter(Boolean).join(" · ");
      }
    } catch (e) { /* 宿主直接塞的文本不是 JSON，原样显示 */ }
  }
  if (m.role === "tool") meta = [meta, m.name || "", m.elapsed_time || ""].filter(Boolean).join(" · ");
  if (m.usage) meta = [meta, formatUsage(m.usage)].filter(Boolean).join(" · ");
  if (meta) head.append(el("span", "meta", meta));
  if (live && m.role === "user" && m.audio_url) {
    const item = fullState.voiceprints?.utterances?.[m.audio_url];
    if (item) {
      if (item.speaker) head.querySelector(".role").textContent = item.speaker;
      const button = el("button", "enroll", item.enrolled_name ? "已录入 · " + item.enrolled_name : "添加录入");
      button.type = "button";
      button.disabled = Boolean(item.error);
      button.title = item.error || "用这句话录入声纹";
      button.addEventListener("click", () => openVoiceprint(m, body));
      head.append(button);
    }
  }
  wrap.append(head);

  if (m.reasoning_content) {  // 开思考时模型的推理过程（reasoning_content），不进 TTS，折叠显示
    const think = el("details", "thinking");
    think.append(el("summary", null, "💭 思考（" + m.reasoning_content.length + " 字）"));
    think.append(el("pre", null, m.reasoning_content));
    wrap.append(think);
  }
  if (m.role === "system") {
    const details = el("details");
    details.open = systemOpen;
    details.append(el("summary", null, "系统提示词（" + body.length + " 字）"));
    details.append(el("pre", null, body));
    details.addEventListener("toggle", () => { systemOpen = details.open; });
    wrap.append(details);
  } else if (m.role === "tool" && body) {  // 工具返回的内容通常很长，默认折叠
    const details = el("details");
    details.append(el("summary", null, "🔧 结果（" + body.length + " 字）"));
    details.append(el("pre", null, body));
    wrap.append(details);
  } else if (body) {
    const bodyEl = el("div", "body", body);
    if (m.audio_url) bodyEl.prepend(renderVoice(m.audio_url));  // ASR 识别这句话时的用户录音
    wrap.append(bodyEl);
  }
  if (instructions) wrap.append(el("div", "instructions", "📋 回复要求：" + instructions));

  for (const call of m.tool_calls || []) {
    const fn = call.function || {};
    wrap.append(el("div", "toolcall", "🔧 " + (fn.name || "") + "(" + (fn.arguments || "") + ")"));
  }
  return wrap;
}

function renderCompressDivider(comp) {
  const wrap = el("div", "compress-divider");
  const details = el("details");
  details.open = compressOpen;
  details.append(el("summary", null,
    "📦 以上 " + comp.cursor + " 条已压缩为摘要（" + comp.summary.length + " 字），发给模型时以摘要替代原文"));
  details.append(el("pre", null, comp.summary));
  details.addEventListener("toggle", () => { compressOpen = details.open; });
  wrap.append(details);
  return wrap;
}

function renderMessages(msgs, comp) {
  const sig = JSON.stringify(msgs) + "|" + JSON.stringify(comp || null) + "|" + JSON.stringify(fullState.voiceprints || null);
  if (sig === lastSig) return;
  lastSig = sig;

  const box = $("#messages");
  const atBottom = box.scrollHeight - box.scrollTop - box.clientHeight < 80;
  const nodes = msgs.map((m) => renderMessage(m, true));
  // 压缩生效后：被摘要覆盖的消息压暗，压缩边界插分隔线（cursor 是去掉 system 后的 history 下标）
  if (comp && comp.summary && comp.cursor > 0) {
    const head = msgs.length && msgs[0].role === "system" ? 1 : 0;
    const end = Math.min(head + comp.cursor, nodes.length);
    for (let i = head; i < end; i++) nodes[i].classList.add("compressed");
    nodes.splice(end, 0, renderCompressDivider(comp));
  }
  if (msgs.length) box.replaceChildren(...nodes);
  else box.replaceChildren(el("div", "empty", "还没有消息"));
  $("#msg-count").textContent = msgs.length + " 条";
  if (atBottom) box.scrollTop = box.scrollHeight;
}

// ---------------- 声纹录入 ----------------

let voiceprintAudioUrl = "";
let voiceprintSaving = false;

function renderVoiceprints() {
  const profiles = fullState.voiceprints?.profiles || [];
  const sync = fullState.voiceprints?.sync || {};
  const syncError = sync.error || fullState.voiceprints?.error || "";
  $("#voiceprint-sync").textContent = syncError ? "已保存的声纹尚未同步：" + syncError
    : !sync.connected ? "等待 ASR 连接后同步声纹"
    : sync.pending ? "正在同步声纹到 ASR…" : "声纹已同步到 ASR，下次说话即可匹配姓名";
  $("#voiceprint-sync").className = "note " + (syncError ? "err" : sync.connected && !sync.pending ? "ok" : "");
  $("#voiceprint-names").replaceChildren(...profiles.map((profile) => {
    const option = el("option");
    option.value = profile.name;
    return option;
  }));
  $("#voiceprint-profiles").replaceChildren(...(profiles.length ? profiles.map((profile) => {
    const row = el("div", "voiceprint-profile");
    row.append(el("span", null, profile.name + " · " + profile.samples + " 个样本"));
    const remove = el("button", null, "删除");
    remove.type = "button";
    remove.disabled = voiceprintSaving;
    remove.setAttribute("aria-label", "删除声纹：" + profile.name);
    remove.addEventListener("click", () => updateVoiceprint("DELETE", {name: profile.name}, "已删除声纹：" + profile.name));
    row.append(remove);
    return row;
  }) : [el("div", "empty", "还没有录入声纹")]));
}

function voiceprintNote(text, ok) {
  $("#voiceprint-note").textContent = text;
  $("#voiceprint-note").className = "note " + (ok ? "ok" : "err");
}

function openVoiceprint(message = null, text = "") {
  voiceprintAudioUrl = message?.audio_url || "";
  const item = fullState.voiceprints?.utterances?.[voiceprintAudioUrl];
  $("#voiceprint-title").textContent = message ? "添加声纹录入" : "声纹";
  $("#voiceprint-form").hidden = !message;
  $("#voiceprint-preview").textContent = text;
  $("#voiceprint-name").value = item?.enrolled_name || "";
  voiceprintNote(fullState.voiceprints?.error || "", false);
  renderVoiceprints();
